  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    // 1. Prepare User Message
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue.trim()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    // 2. Prepare Assistant Message Placeholder
    const assistantMessageId = (Date.now() + 1).toString();
    setMessages(prev => [...prev, {
      id: assistantMessageId,
      role: 'assistant',
      content: ''
    }]);

    try {
      // API Key Hardcoded as requested
      // TODO: Replace the placeholder string below with your actual OpenRouter key
      const apiKey = "sk-or-REPLACE_THIS_WITH_YOUR_KEY";

      if (!apiKey || apiKey.includes('REPLACE_THIS_WITH_YOUR_KEY')) {
        throw new Error("API Key is missing. Please replace the placeholder in AiAssistant.tsx with your actual OpenRouter key.");
      }

      // 3. Construct API Request Payload for OpenRouter (using OpenAI model)
      const payload = {
        model: "openai/gpt-4o-mini", // Using OpenAI model via OpenRouter
        messages: [
          { role: "system", content: systemInstruction },
          // Include chat history (excluding the first welcome msg and the new user message which we add manually)
          ...messages
            .filter(m => m.id !== 'init' && !m.isError)
            .map(m => ({
              role: m.role,
              content: m.content
            })),
          { role: "user", content: userMessage.content }
        ],
        stream: true
      };

      const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${apiKey}`,
          "Content-Type": "application/json",
          "HTTP-Referer": window.location.origin, // OpenRouter requirement
          "X-Title": "Alex Portfolio"
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        const errData = await response.json().catch(() => ({}));
        throw new Error(errData.error?.message || `API Error: ${response.statusText}`);
      }

      if (!response.body) throw new Error("No response body");

      // 4. Stream Handling
      const reader = response.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let fullText = '';
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        buffer += chunk;

        const lines = buffer.split('\n');
        buffer = lines.pop() || ''; // Keep the last partial line in buffer

        for (const line of lines) {
          const trimmedLine = line.trim();
          if (!trimmedLine.startsWith('data: ')) continue;

          const dataStr = trimmedLine.replace('data: ', '');
          if (dataStr === '[DONE]') continue;

          try {
            const data = JSON.parse(dataStr);
            const delta = data.choices?.[0]?.delta?.content || '';
            if (delta) {
              fullText += delta;
              setMessages(prev => prev.map(msg => 
                msg.id === assistantMessageId 
                  ? { ...msg, content: fullText }
                  : msg
              ));
            }
          } catch (e) {
            console.warn("Error parsing chunk", e);
          }
        }
      }

    } catch (error: any) {
      console.error('API Error:', error);

      const errorMessage = error instanceof Error ? error.message : "Unknown error occurred";

      // Remove the empty loading message and add error message
      setMessages(prev => {
        const withoutLoading = prev.filter(msg => msg.id !== assistantMessageId);
        return [...withoutLoading, {
          id: Date.now().toString(),
          role: 'assistant',
          isError: true,
          content: `**Ошибка API:** ${errorMessage}`
        }];
      });
    } finally {
      setIsLoading(false);
    }
  };

  // Helper to check if the last message is an empty assistant message (waiting for stream)
  const isWaitingForFirstChunk = isLoading && messages.length > 0 && messages[messages.length - 1].role === 'assistant' && messages[messages.length - 1].content.length === 0;

  return (
    <>
